#include "timer.h"
#include "main.h"
#include "sensors.h"
#include <cstdio>
/*
-----------------DO NOT EDIT THIS FILE-----------------
*/

int timerMs = 0;
bool runTimer = false;

void startTimer(void* param) {
    runTimer = true;
    timerMs = 0;
    char buf[48];
    while (true) {
        if (master.get_digital_new_press(pros::E_CONTROLLER_DIGITAL_A)) {
            if (runTimer) {
                stopTimer();
            } else {
                runTimer = true;
                timerMs = 0;
            }
        }
        if (runTimer) {
            if (false) {//getLeftOpticalData().blue < 200 && getRightOpticalData().blue < 200
                snprintf(buf, sizeof(buf), "You won in %d.%03d sec", timerMs / 1000, timerMs % 1000);
                pros::lcd::set_text(2, buf);
                runTimer = false;
            } else {
                snprintf(buf, sizeof(buf), "%d.%03d sec", timerMs / 1000, timerMs % 1000);
                pros::lcd::set_text(2, buf);
                timerMs += 20;
            }
        }
        pros::delay(20);
    }
}

void stopTimer() {
    runTimer = false;
    timerMs = 0;
}
